    aot=b.get('aot') or {}
    if not aot.get('supported'): continue
    for i,p in enumerate(aot.get('params') or []):
        if p.get('type') in SCALAR and p.get('default') is None and p.get('optional'):
            hits.append((b.get('canonical_name'), i, p.get('name'), p.get('type')))
print(len(hits),'optional scalar params whose declared default is null')
